try {
  var body = $('Webhook').first().json.body || {};
  var sessionRows = $('Load Session').all();
  var config = $('⚙️ Client Config').first().json;
  var phone = body.phone || '';
  var userMessage = body.message || '';
  var sessionId = 'session_' + phone;

  var existingMessages = [];
  if (sessionRows.length > 0 && sessionRows[0].json && sessionRows[0].json.messages) {
    var raw = sessionRows[0].json.messages;
    try { existingMessages = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch(pe) { existingMessages = []; }
  }

  var messages = existingMessages.concat([{ role: 'user', content: userMessage }]);

  var tools = [
    { name: 'check_availability', description: 'Check available appointment slots for a given date', input_schema: { type: 'object', properties: { preferredDate: { type: 'string', description: 'The date the customer asked for. Accepts natural language exactly as they said it (today, tomorrow, Thursday, next Monday) or YYYY-MM-DD. Prefer passing their own words through.' } }, required: ['preferredDate'] } },
    { name: 'book_house_visit', description: 'Book a house visit appointment for a solar or battery storage survey', input_schema: { type: 'object', properties: { date: { type: 'string', description: 'The date the customer agreed. Accepts natural language exactly as they said it (tomorrow, Friday, next Monday) or YYYY-MM-DD. Prefer passing their own words through.' }, time: { type: 'string', description: 'Slot time e.g. 9am, 10am, 11am, 12pm, 1pm, 2pm, 3pm, 4pm, 5pm' }, service: { type: 'string', description: 'Service type' }, address: { type: 'string', description: 'Property address' }, name: { type: 'string', description: 'Customer full name' }, email: { type: 'string', description: 'Customer email' } }, required: ['date','time','service','address','name','email'] } },
    { name: 'cancel_booking', description: 'Cancel an existing confirmed appointment', input_schema: { type: 'object', properties: { reason: { type: 'string', description: 'Reason for cancellation' } } } },
    { name: 'reschedule_booking', description: 'Reschedule an existing appointment to a new date and time', input_schema: { type: 'object', properties: { newDate: { type: 'string', description: 'The new date the customer asked for. Accepts natural language exactly as they said it (tomorrow, Friday, next Monday) or YYYY-MM-DD. Prefer passing their own words through.' }, newTime: { type: 'string', description: 'Slot time e.g. 9am, 10am, 11am, 12pm, 1pm, 2pm, 3pm, 4pm, 5pm' } }, required: ['newDate','newTime'] } },
    { name: 'handle_dnc', description: 'Opt customer out of all future communications (do not contact)', input_schema: { type: 'object', properties: {} } },
    { name: 'take_message', description: 'Record a message for the human team to follow up. Call this whenever the customer needs a person rather than you: a complaint, a technical fault with an existing installation, a commercial or large-building enquiry, a recruitment enquiry, or an explicit request to speak to someone. Call it instead of only reading out the phone number, so the request is actually recorded.', input_schema: { type: 'object', properties: { message: { type: 'string', description: 'What the customer needs, in one or two plain sentences in your own words.' }, name: { type: 'string', description: 'Customer name if you know it, otherwise leave empty.' }, urgency: { type: 'string', description: 'urgent for faults or complaints, normal for general follow-up, low for recruitment or non-urgent enquiries' } }, required: ['message'] } }
  ];

  return [{ json: { phone: phone, sessionId: sessionId, userMessage: userMessage, messages: messages, tools: tools, isExistingSession: sessionRows.length > 0 } }];
} catch (e) {
  return [{ json: { phone: '', sessionId: '', userMessage: '', messages: [], tools: [], error: e.message } }];
}

try {
  var response = $input.first().json;
  var config = $('⚙️ Client Config').first().json;
  var phone = config.businessPhone || '';
  var phoneValid = phone && phone !== 'ADD_PHONE_BEFORE_ACTIVATION';
  var phoneMsg = phoneValid ? ' or call us on ' + phone : '';
  if (!response.content || !response.stop_reason) {
    return [{ json: { stopReason: 'end_turn', textContent: "I'm having trouble right now. Please try again in a moment" + phoneMsg + ".", toolUseBlock: null, fullContent: [], apiError: true } }];
  }
  var content = response.content || [];
  var stopReason = response.stop_reason || 'end_turn';
  var textContent = '';
  var toolUseBlock = null;
  for (var i = 0; i < content.length; i++) {
    var block = content[i];
    if (block.type === 'text') { textContent = block.text || ''; }
    else if (block.type === 'tool_use' && !toolUseBlock) { toolUseBlock = block; }
  }
  return [{ json: { stopReason: stopReason, textContent: textContent, toolUseBlock: toolUseBlock, fullContent: content } }];
} catch (e) {
  var cfg = $('⚙️ Client Config').first().json;
  var ph = cfg.businessPhone || '';
  var phValid = ph && ph !== 'ADD_PHONE_BEFORE_ACTIVATION';
  var phMsg = phValid ? ' or call us on ' + ph : '';
  return [{ json: { stopReason: 'end_turn', textContent: "I'm having trouble right now. Please try again in a moment" + phMsg + ".", toolUseBlock: null, fullContent: [], error: e.message } }];
}

try {
  var payload = $('Build Claude Payload').first().json;
  var parseR1 = $('Parse Response R1').first().json;
  var replyText = parseR1.textContent || 'Thank you for your message.';
  var rawContent = parseR1.fullContent || [];
  var safeContent = [];
  for (var ci = 0; ci < rawContent.length; ci++) {
    if (rawContent[ci] && rawContent[ci].type === 'text') { safeContent.push(rawContent[ci]); }
  }
  // An empty array is TRUTHY in JS, so `filter(...) || fallback` never fires.
  // Saving content: [] poisons the stored session permanently for this phone —
  // every later Anthropic call 400s on the empty assistant turn. Check length.
  if (safeContent.length === 0) { safeContent = [{ type: 'text', text: replyText }]; }
  var updatedMessages = payload.messages.concat([{ role: 'assistant', content: safeContent }]);
  return [{ json: { message: replyText.replace(/\n{3,}/g, '\n\n').trim(), sessionId: payload.sessionId, phone: payload.phone, updatedMessages: updatedMessages } }];
} catch (e) {
  return [{ json: { message: 'Thank you for your message.', sessionId: $('Build Claude Payload').first().json.sessionId || '', phone: $('Build Claude Payload').first().json.phone || '', updatedMessages: $('Build Claude Payload').first().json.messages || [] } }];
}

try {
  var parseR1 = $('Parse Response R1').first().json;
  var payload = $('Build Claude Payload').first().json;
  var toolBlock = parseR1.toolUseBlock || {};
  return [{ json: { toolName: toolBlock.name || '', toolInput: toolBlock.input || {}, toolUseId: toolBlock.id || '', phone: payload.phone, sessionId: payload.sessionId, claudeResponseContent: parseR1.fullContent || [] } }];
} catch (e) {
  return [{ json: { toolName: 'get_business_info', toolInput: { topic: 'about' }, toolUseId: 'err', phone: $('Build Claude Payload').first().json.phone || '', sessionId: $('Build Claude Payload').first().json.sessionId || '', claudeResponseContent: [] } }];
}

try {
