// BUG-R38: Twilio hard-rejects a body over 1600 chars (error 21617) and the customer
// gets NOTHING. Split into whole messages at paragraph boundaries instead of truncating.
// Emitting multiple items makes the Execute Workflow node call WF-C4 once per chunk.
try {
  var src = $('Prep Direct Reply').first().json || {};
  var phone = src.phone || '';
  var msg = String(src.message || '');
  var LIMIT = 1500; // headroom under Twilio's 1600
  var MAX = 3;      // never spam more than three messages at a customer

  if (msg.length <= LIMIT) { return [{ json: { phone: phone, message: msg } }]; }

  function hardSplit(text, limit) {
    var out = []; var t = text;
    while (t.length > limit) {
      var cut = t.lastIndexOf(' ', limit);
      if (cut < limit * 0.5) { cut = limit; }
      out.push(t.substring(0, cut).trim());
      t = t.substring(cut).trim();
    }
    if (t.length > 0) { out.push(t); }
    return out;
  }

  var paras = msg.split(/\n\n+/);
  var chunks = []; var cur = '';
  for (var i = 0; i < paras.length; i++) {
    var p = paras[i];
    if (p.length > LIMIT) {
      if (cur) { chunks.push(cur); cur = ''; }
      var hs = hardSplit(p, LIMIT);
      for (var j = 0; j < hs.length; j++) { chunks.push(hs[j]); }
      continue;
    }
    if (cur === '') { cur = p; }
    else if ((cur.length + 2 + p.length) <= LIMIT) { cur = cur + '\n\n' + p; }
    else { chunks.push(cur); cur = p; }
  }
  if (cur) { chunks.push(cur); }

  if (chunks.length > MAX) {
    chunks = chunks.slice(0, MAX);
    chunks[MAX - 1] = chunks[MAX - 1] + '\n\nThere is a bit more to cover — what would you like me to go into?';
  }

  var items = [];
  for (var k = 0; k < chunks.length; k++) { items.push({ json: { phone: phone, message: chunks[k] } }); }
  return items;
} catch (e) {
  var f = {};
  try { f = $('Prep Direct Reply').first().json || {}; } catch (x) {}
  return [{ json: { phone: f.phone || '', message: String(f.message || '').substring(0, 1500) } }];
}

