// BUG-R40: two messages from the same person, sent a second apart, both read the
// session BEFORE either had written back — so the second overwrote the first and
// the earlier exchange vanished. Measured: 1s gaps lost 2 of 3 messages, 8s gaps
// lost none, because the danger window is however long the reply takes (5-15s).
//
// Fix: re-read the session HERE, immediately before the write, and append ONLY our
// own exchange to whatever is there now. That shrinks the window from the whole
// think-time down to the few hundred ms between this read and the save.
try {
  var mine = $('Build Direct Reply').first().json || {};
  var payload = $('Build Claude Payload').first().json || {};
  var updated = mine.updatedMessages || [];

  // payload.messages = history-at-read + our user message, so everything from that
  // index onward is ours alone. Works for both the direct and tool paths.
  var historyLen = (payload.messages || []).length - 1;
  if (historyLen < 0) { historyLen = 0; }
  var myExchange = updated.slice(historyLen);
  if (myExchange.length === 0) { myExchange = updated; }

  var rows = $input.all();
  var current = null;
  if (rows.length > 0 && rows[0].json && rows[0].json.messages) {
    var raw = rows[0].json.messages;
    try { current = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (pe) { current = null; }
  }

  // If the re-read failed or returned nothing usable, fall back to exactly the old
  // behaviour. A Supabase blip must never wipe a session.
  var finalMessages;
  if (current && Object.prototype.toString.call(current) === '[object Array]') {
    finalMessages = current.concat(myExchange);
  } else {
    finalMessages = updated;
  }

  return [{ json: { sessionId: mine.sessionId || payload.sessionId, phone: mine.phone || payload.phone, updatedMessages: finalMessages } }];
} catch (e) {
  var f = $('Build Direct Reply').first().json || {};
  return [{ json: { sessionId: f.sessionId || '', phone: f.phone || '', updatedMessages: f.updatedMessages || [] } }];
}

